from pathlib import Path
import json,hashlib,re
p=Path(__file__).resolve().parent;read=lambda n:json.loads((p/n).read_text())
s=(p/'tests.log').read_text();tests=int(re.search(r'^# tests (\d+)$',s,re.M)[1]);assert tests==1551 and re.search(r'^# pass 1551$',s,re.M) and re.search(r'^# fail 0$',s,re.M)
hashes={str(f.relative_to(p/'runtime')):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted((p/'runtime').rglob('*')) if f.is_file()};assert hashes==read('bench-runtime-sha256.json')
j=read('mixed-jsc-results.json');assert j['baselineVersion']=='3.1.2' and j['candidateVersion']=='3.1.3' and len(j['runs'])==360
ranges=[]
for mode in ['cold','sequence']:
 for mixed in [False,True]:
  rows=[r for r in j['comparisons'] if r['mode']==mode and r['mixedPolicy']==mixed]
  delta=lambda k:[round(100*(r['candidate'][k]/r['baseline'][k]-1),3) for r in rows]
  a,b=delta('sampledPeakFootprint'),delta('milliseconds');ranges.append({'mode':mode,'mixed':mixed,'scenarios':len(rows),'peakFootprintPercent':[min(a),max(a)],'elapsedPercent':[min(b),max(b)]})
native=[]
for n in ['native-first-load-results.json','native-filled-first-load-results.json']:
 d=read(n);assert len(d['runs'])==312
 rows=[]
 for r in d['comparisons']:
  a,b=r['baseline'],r['candidate'];rows.append({'scenario':r['scenario'],'baselineMs':a['medianMs'],'candidateMs':b['medianMs'],'elapsedPercent':round(100*(b['medianMs']/a['medianMs']-1),3),'peakHeapPercent':round(100*(b['sampledMaxHeapBytes']/a['sampledMaxHeapBytes']-1),3),'incrementalHeapPercent':round(100*(b['medianHeapGrowth']/a['medianHeapGrowth']-1),3)})
 native.append({'report':n,'processes':312,'scenarios':rows})
churn=read('mixed-native-churn-results.json')['results'];assert len(churn)==20
for r in churn:assert r['httpCalls']==120 and r['warmHTTP']==r['activeHTTP']==0 and r['maxActiveHTTP']==1 and r['lyricResponses']==r['completedResponses']==240 and r['maxCacheCharacters']<=(32000 if r['mode']=='compact' else 64000)
plain=read('native-churn-results.json')['results'];assert len(plain)==12
for r in plain:assert r['trackChanges']==240 and r['httpCalls']==720 and r['maxActiveHTTP']==1
pressure=read('native-pressure-results.json');assert len(pressure['runs'])==16
for r in pressure['runs']:assert r['peakHTTP']==1 and r['peakLiveInvocations']<=2 and r['admissionTimers']==0 and r['retryTranslated']==1
backoff=read('backoff-work-results.json');assert len(backoff['results'])==8
for r in backoff['results']:assert r['completed']==10 and r['badHostRequests']==(10 if r['version']=='3.1.2' else 1)
live=read('mixed-live-results.json');assert len(live['results'])==2
for r in live['results']:assert r['changed']==6 and r['warmHTTP']==0 and len(r['calls'])==1 and len(r['calls'][0]['queries'])==5
runtime=read('runtime-manifest.json');size=next(r['bytes'] for r in runtime if r['path']=='Loon/script/SpotifyLyrics.js')
summary={'version':'3.1.3','adapter':14,'baselineVersion':'3.1.2','baselineRuntime':'eb45d9ea239fdd649d4d22c0695435531f986de3','tests':{'passed':tests,'failed':0,'addedSince312':tests-1515,'egernYAML':'passed'},'loonRuntime':{'bytes':size,'baselineBytes':97832,'reductionPercent':round((97832-size)/97832*100,3)},'work':read('work-reproduction.json'),'liveRequests':{'candidate':2,'rowsPerTarget':6,'uniqueQueriesPerRequest':5,'warmHTTP':0},'jsc':{'processes':360,'ranges':ranges},'nativeFirstLoad':native,'plainChurn':{'processes':12,'distinctSongsPerProcess':240,'httpPerProcess':720,'loon':[r for r in plain if r['client']=='Loon']},'mixedChurn':{'configurations':20,'songsPerConfiguration':120,'responses':4800,'httpCalls':2400,'warmHTTP':0,'unfinishedHTTP':0,'maxActiveHTTP':1,'standardMaxCharacters':max(r['maxCacheCharacters'] for r in churn if r['mode']=='standard'),'compactMaxCharacters':max(r['maxCacheCharacters'] for r in churn if r['mode']=='compact')},'pressure':{'processes':16,'maxLiveInvocations':2,'maxActiveHTTP':1,'admissionTimers':0,'retryTranslationRetained':True},'badService':backoff,'runtimeSHA256':hashes,'scope':'Same-fixture local comparisons, public macOS JavaScriptCore and native-interface Node mocks, two live synthetic translation requests. Includes CPU/heap regressions as well as improvements. Not native app import, every allocation, iPhone host/network-buffer memory or VPN stability acceptance.'}
(p/'validation-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
lines=['# VerseLyrics 3.1.3 measurements','',f'**{tests} automated tests pass, zero fail**, 36 added since 3.1.2; native Egern YAML passes. Baseline is published 3.1.2 immutable commit eb45d9ea239fdd649d4d22c0695435531f986de3. Adapter 14 and existing limits remain. Runtime hashes below and bench-runtime-sha256.json bind all measurements to final bytes.','', '## Work and functionality','',f'Loon lyric runtime: **{size:,} bytes**, compared with 97,832 bytes before ({summary["loonRuntime"]["reductionPercent"]}% smaller). This is script/download size, not a RAM guarantee. All 6,447 Han mappings and nonmapped samples remain; planes load lazily, with no full decompression or Map.','', 'Actual baseline/candidate source reproduction gives:','', '| Scenario | 3.1.2 | 3.1.3 |','| --- | --- | --- |','| 48 mixed rows sharing Latin spans | 48 q items | 1 q item |','| Normalize 120 chorus rows with eight unique pairs | 240 calls | 16 calls |','| Save with 24 retained metadata entries | 48 entry JSON parses | 24 entry JSON parses |','', 'Both versions use one HTTP for the 48-row example and produce all 48 translations. Query counts must not be described as HTTP request counts. Cache characters are unchanged. See work-reproduction.json and runnable reproduce-work.mjs.','', 'Two fresh public requests through the candidate translator use six self-written mixed rows per target with five unique q values, retain literal Chinese and produce six translated rows. Warm reopen uses zero HTTP. Exact service responses are in mixed-live-results.json. No account credentials, private Spotify traffic or copied song lyrics are used.','', '## Cold JavaScriptCore and 32-context sequences','', '360 fresh macOS public-JSC processes: six alternating trials per version/scenario, twenty cold cases and ten 32-context sequence cases. HTTP mocks have zero latency and callbacks drain before completion. All output hashes, bytes and HTTP counts agree with functional 3.1.2; mixed cases reduce q/reply sizes. No forced GC between sequence contexts.','', '| Mode | Cases | Peak footprint change | Elapsed change |','| --- | --- | --- | --- |']
for r in ranges:lines.append(f'| {r["mode"]} '+('mixed' if r['mixed'] else 'existing')+f' | {r["scenarios"]} | {r["peakFootprintPercent"]}% | {r["elapsedPercent"]}% |')
lines += ['', '## First-load Node comparisons','', 'Thirteen scenarios include ordinary foreign lyrics, missing lyrics with/without metadata, Chinese-to-English, repeated chorus, mixed Chinese/English and pure Chinese preservation. Twelve fresh processes per version/scenario: 312 cold and 312 populated-cache processes. Both versions use one shared fixture codec; only the actual client runtime differs. This avoids source-version differences in the harness. Populated caches contain 48,000-60,000 unrelated characters. Native output hashes and HTTP counts must agree. V8 old-space is set to 32 MiB for the harness, not a Loon memory limit.','', '| Cache | Scenario | Before ms | After ms | Time change | Peak heap change |','| --- | --- | --- | --- | --- | --- |']
for group in native:
 for r in group['scenarios']:lines.append(f'| '+('populated' if 'filled' in group['report'] else 'cold')+f' | {r["scenario"]} | {r["baselineMs"]} | {r["candidateMs"]} | {r["elapsedPercent"]}% | {r["peakHeapPercent"]}% |')
lines += ['', 'Negative percentages are reductions. Some cases regress in time or sampled heap; no universal reduction is claimed. Raw runs retain absolute peaks, incremental growth and pre-invocation heap. Samples include fixture/VM/compiler/allocator effects and are not every allocation or iPhone networking.','', '## Continuous songs and pressure','', 'Twelve separate native playlist processes compare Loon baseline plus all five candidate clients in JSON/protobuf. Each processes 240 distinct cold song IDs, 720 sequential metadata/source/translation/color HTTP calls, and bounded eviction. All body/content SHA256 results match. Twenty more processes cover five clients, two formats and two cache modes: 120 mixed-song IDs, 240 responses per process, total 4,800 fresh native responses and 2,400 translation HTTP calls. Reopen uses zero HTTP, with zero unfinished callbacks and maximum one active HTTP. Fresh VM invocation and explicit GC every six songs are harness behavior, not native reclamation evidence.',f'Mixed cache maximum: {summary["mixedChurn"]["standardMaxCharacters"]} / 64,000 standard and {summary["mixedChurn"]["compactMaxCharacters"]} / 32,000 compact characters. Existing 128/64 entry caps remain.','', '| Loon playlist | Version | Elapsed ms | Sampled peak heap bytes |','| --- | --- | --- | --- |']
for r in summary['plainChurn']['loon']:lines.append(f'| {r["format"]} | {r["version"]} | {r["elapsedMs"]} | {r["sampledMaxHeapBytes"]} |')
lines += ['', 'The playlist peak is a sampled whole-process heap and can increase on one representation even when another decreases; no iPhone extrapolation is made. Sixteen delayed-callback pressure processes cover 60 arrivals every two milliseconds and 400 ms callbacks. Maximum two live invocations, one active HTTP, no admission timers; settled retry retains translation. Native storage atomicity is not assumed.','', '## Invalid service response backoff','', 'Compiled Loon baseline and candidate are run against the same 90,013-byte malformed ASCII HTML with HTTP 200. Across ten songs in either representation, the translator bad-host requests decrease from ten to one; malformed-first-source requests also decrease from ten to one while all twenty valid QQ requests and ten successful fallbacks remain. Output hashes match. Failure does not store a no-lyrics proof or renew the deadline; expiry allows retry. All five adapters and both representations exercise this behavior in the regression suite. These are deterministic HTTP mocks, not live failure captures.','', '## Reproduction and boundary','', 'Build and run tests/Ruby as listed in README.md. Generate fixtures and compile jsc-memory-runner.c using the public macOS SDK/JavaScriptCore framework. Run `python3 run-final-313.py /path/to/node /path/to/312`; the driver rejects runtime changes between steps. Work/callback/cache measurements use self-written fixtures. `node mixed-live-check.mjs` is a separate live public-service observation and may change with the service.','', 'No iPhone/client import or VPN acceptance was performed. Loon native buffers, OS lifetime and process ceiling cannot be guaranteed by these JavaScript measurements. Cache capacity, source/body/URL/character/time limits, native completion, six-source fallback, mixed-English translation, Chinese conversion filtering and native timing/highlighting are retained.','']
(p/'MEASUREMENTS.md').write_text('\n'.join(lines));print(json.dumps({'tests':tests,'runtime':summary['loonRuntime'],'jscProcesses':360,'coldProcesses':624,'mixedResponses':4800,'scope':summary['scope']}))
